proposed.setup:
globalThis.notices = [];
globalThis.dialogOpens = [];
globalThis.dialogCloses = 0;
globalThis.uidN = 0;
globalThis.ARC = {state:{ui:{}},route:function(){return {name:'workbook',params:['wb-q3-sales']};},save:function(){},render:function(){},notify:function(m){globalThis.notices.push(String(m));},esc:function(s){return String(s==null?'':s);},uid:function(p){globalThis.uidN = globalThis.uidN + 1; return String(p)+'-'+globalThis.uidN;},openDialog:function(html,opts){globalThis.dialogOpens.push({html:String(html),title:opts&&opts.title});},closeDialog:function(){globalThis.dialogCloses = globalThis.dialogCloses + 1;},setInert:function(){},openPopover:function(){},closePopover:function(){},combobox:function(){return '';},dialogOpen:false};
globalThis.ARC.state.ui.workbooks = JSON.parse(JSON.stringify(window.SEED.workbooks));
globalThis.wb = globalThis.ARC.state.ui.workbooks[0];
globalThis.sheet = globalThis.wb.sheets[0];
globalThis.sheet.sel = {r1:0,c1:0,r2:3,c2:2};

proposed.precondition:
assert.strictEqual(wb.id, 'wb-q3-sales');
assert.strictEqual(sheet.name, 'Sheet1');
assert.strictEqual(sheet.cells.A1, 'Region');
assert.strictEqual(sheet.cells.B1, 'Sales');
assert.strictEqual(sheet.cells.C1, 'Status');
assert.deepStrictEqual(sheet.sel, {r1:0,c1:0,r2:3,c2:2});
assert.strictEqual(sheet.filters.length, 0);

proposed.check:
assert.strictEqual(typeof createFilter, 'function');
assert.strictEqual(typeof openFilterDialog, 'function');
createFilter({});
const flist = ARC.state.ui.filters[sheet.id];
assert.ok(Array.isArray(flist) && flist.length === 1, 'Create filter registers exactly one filter view for the sheet');
const filter = flist[0];
assert.deepStrictEqual(filter.range, {r1:0,c1:0,r2:3,c2:2});
globalThis.dialogOpens.length = 0;
globalThis.dialogCloses = 0;
openFilterDialog({data:{id:'0',filter:filter.id}});
assert.strictEqual(globalThis.dialogOpens.length, 1, 'clicking the header button "Filter Region" must present the filter dialog for that header');
const html = globalThis.dialogOpens[0].html;
assert.ok(/Clear selection/.test(html), 'the value filter dialog provides "Clear selection"');
assert.ok(html.indexOf('name="v"') >= 0, 'the value filter dialog provides value checkboxes');
assert.ok(/East/.test(html) && /North/.test(html) && /South/.test(html), 'checkboxes are generated from the distinct Region source values');
assert.ok(/Apply/.test(html), 'the value filter dialog provides "Apply"');

