proposed.setup:
globalThis.notices = [];
globalThis.uidN = 0;
globalThis.ARC = {state:{ui:{}},route:function(){return {name:'workbook',params:['wb-q3-sales']};},save:function(){},render:function(){},notify:function(m){globalThis.notices.push(String(m));},esc:function(s){return String(s==null?'':s);},uid:function(p){globalThis.uidN = globalThis.uidN + 1; return String(p)+'-'+globalThis.uidN;},openDialog:function(){},closeDialog:function(){},setInert:function(){},openPopover:function(){},closePopover:function(){},combobox:function(){return '';},dialogOpen:false};
globalThis.ARC.state.ui.workbooks = JSON.parse(JSON.stringify(window.SEED.workbooks));
globalThis.wb = globalThis.ARC.state.ui.workbooks[0];
globalThis.sheet = globalThis.wb.sheets[0];
globalThis.sheet.cells.B2 = '20';
globalThis.sheet.cells.B3 = '50';
globalThis.sheet.cells.B4 = '80';
globalThis.sheet.validations = [{id:'vr-1', range:{r1:1,c1:1,r2:3,c2:1}, type:'number', min:0, max:100}];

proposed.check:
assert.strictEqual(typeof commitCell, 'function');
assert.strictEqual(commitCell(wb, sheet, 2, 1, '101'), false, 'control: 101 is rejected by the persisted 0-to-100 rule on B2:B4');
assert.strictEqual(sheet.cells.B3, '50', 'control: the rejected edit leaves the original value in place');
assert.strictEqual(globalThis.notices[globalThis.notices.length - 1], 'Please enter a number from 0 to 100');
assert.strictEqual(commitCell(wb, sheet, 2, 1, '12abc'), false, 'a non-numeric value is not a valid number for the 0-to-100 rule, so the whole write must be rejected');
assert.strictEqual(sheet.cells.B3, '50', 'the original value must remain after a rejected write');

